async function enhanceV2Positions(positions, provider, userAddress, chainId) {
  if (positions.length === 0) return [];
  const multicallContract = getContract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
  if (!multicallContract) return positions;
  const pairInterface = new Contract(positions[0].poolId, V2_PAIR_ABI).interface;
  const gaugeInterface = new Contract(ethers.constants.AddressZero, GAUGE_ABI).interface;
  const calls = [];
  const callMap = [];
  positions.forEach((pos) => {
    const startIndex = calls.length;
    calls.push({
      target: pos.poolId,
      callData: pairInterface.encodeFunctionData("balanceOf", [userAddress])
    });
    let gaugeBalanceIndex;
    if (pos.gaugeAddress) {
      gaugeBalanceIndex = calls.length;
      calls.push({
        target: pos.gaugeAddress,
        callData: gaugeInterface.encodeFunctionData("balanceOf", [userAddress])
      });
    }
    const totalSupplyIndex = calls.length;
    calls.push({
      target: pos.poolId,
      callData: pairInterface.encodeFunctionData("totalSupply", [])
    });
    const reservesIndex = calls.length;
    calls.push({
      target: pos.poolId,
      callData: pairInterface.encodeFunctionData("getReserves", [])
    });
    callMap.push({
      walletBalanceIndex: startIndex,
      gaugeBalanceIndex,
      totalSupplyIndex,
      reservesIndex
    });
  });
  try {
    const batchSize = 500;
    const allResults = [];
    for (let i = 0; i < calls.length; i += batchSize) {
      const batch = calls.slice(i, i + batchSize);
      const [, returnData] = await multicallContract.callStatic.aggregate(batch);
      allResults.push(...returnData);
    }
    return positions.map((pos, index) => {
      try {
        const indices = callMap[index];
        const walletBalance = pairInterface.decodeFunctionResult("balanceOf", allResults[indices.walletBalanceIndex])[0];
        let gaugeBalance = BigNumber.from(0);
        if (indices.gaugeBalanceIndex !== void 0) {
          try {
            gaugeBalance = gaugeInterface.decodeFunctionResult("balanceOf", allResults[indices.gaugeBalanceIndex])[0];
          } catch (error) {
            console.warn(`\u26A0\uFE0F [V2 ENHANCE] Failed to decode gauge balance for position ${index}:`, error);
          }
        }
        const totalBalance = walletBalance.add(gaugeBalance);
        const totalSupply = pairInterface.decodeFunctionResult("totalSupply", allResults[indices.totalSupplyIndex])[0];
        const reserves = pairInterface.decodeFunctionResult("getReserves", allResults[indices.reservesIndex]);
        const token0Decimals = pos.currency0Amount.currency.decimals;
        const token1Decimals = pos.currency1Amount.currency.decimals;
        const totalUserBalance = parseFloat(ethers.utils.formatUnits(totalBalance, 18));
        const totalSupplyFormatted = parseFloat(ethers.utils.formatUnits(totalSupply, 18));
        const shareOfPool = totalSupplyFormatted > 0 ? totalUserBalance / totalSupplyFormatted : 0;
        const reserve0 = parseFloat(ethers.utils.formatUnits(reserves.reserve0, token0Decimals));
        const reserve1 = parseFloat(ethers.utils.formatUnits(reserves.reserve1, token1Decimals));
        const token0Amount = shareOfPool * reserve0;
        const token1Amount = shareOfPool * reserve1;
        const safeToken0Amount = Math.min(Math.max(token0Amount, 0), 1e6);
        const safeToken1Amount = Math.min(Math.max(token1Amount, 0), 1e6);
        const token0AmountFormatted = safeToken0Amount.toFixed(Math.min(token0Decimals, 6));
        const token1AmountFormatted = safeToken1Amount.toFixed(Math.min(token1Decimals, 6));
        const token0AmountWei = ethers.utils.parseUnits(token0AmountFormatted, token0Decimals).toString();
        const token1AmountWei = ethers.utils.parseUnits(token1AmountFormatted, token1Decimals).toString();
        const enhancedCurrency0Amount = CurrencyAmount.fromRawAmount(
          pos.currency0Amount.currency,
          token0AmountWei
        );
        const enhancedCurrency1Amount = CurrencyAmount.fromRawAmount(
          pos.currency1Amount.currency,
          token1AmountWei
        );
        const enhancedPair = new Pair(
          CurrencyAmount.fromRawAmount(pos.currency0Amount.currency, reserves.reserve0.toString()),
          CurrencyAmount.fromRawAmount(pos.currency1Amount.currency, reserves.reserve1.toString())
        );
        const enhancedTotalSupply = pos.totalSupply ? CurrencyAmount.fromRawAmount(pos.totalSupply.currency, totalSupply.toString()) : void 0;
        console.log(`\u2705 [V2 ENHANCE] ${pos.currency0Amount.currency.symbol}/${pos.currency1Amount.currency.symbol}:`, {
          walletBalance: ethers.utils.formatUnits(walletBalance, 18),
          gaugeBalance: ethers.utils.formatUnits(gaugeBalance, 18),
          totalBalance: ethers.utils.formatUnits(totalBalance, 18),
          oldAmount0: pos.currency0Amount.toSignificant(6),
          newAmount0: enhancedCurrency0Amount.toSignificant(6),
          oldAmount1: pos.currency1Amount.toSignificant(6),
          newAmount1: enhancedCurrency1Amount.toSignificant(6),
          shareOfPool: (shareOfPool * 100).toFixed(4) + "%",
          isStaked: pos.isStaked,
          gaugeAddress: pos.gaugeAddress
        });
        return {
          ...pos,
          currency0Amount: enhancedCurrency0Amount,
          currency1Amount: enhancedCurrency1Amount,
          pair: enhancedPair,
          totalSupply: enhancedTotalSupply,
          liquidityAmount: CurrencyAmount.fromRawAmount(
            pos.liquidityAmount?.currency || pos.liquidityToken,
            totalBalance.toString()
          )
        };
      } catch (error) {
        console.warn(`\u26A0\uFE0F [V2 ENHANCE] Failed to enhance position ${index}:`, error);
        return pos;
      }
    });
  } catch (error) {
    console.error("\u274C [V2 ENHANCE] Multicall failed:", error);
    return positions;
  }
}
async function enhanceV3Positions(positions, provider, chainId) {
  if (positions.length === 0) return [];
  const multicallContract = getContract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
  if (!multicallContract) return positions;
  const poolGroups = /* @__PURE__ */ new Map();
  positions.forEach((pos) => {
    if (!poolGroups.has(pos.poolId)) {
      poolGroups.set(pos.poolId, []);
    }
    poolGroups.get(pos.poolId).push(pos);
  });
  const poolInterface = new Contract(Array.from(poolGroups.keys())[0], V3_POOL_ABI).interface;
  const calls = Array.from(poolGroups.keys()).flatMap((poolAddress) => [
    {
      target: poolAddress,
      callData: poolInterface.encodeFunctionData("slot0", [])
    },
    {
      target: poolAddress,
      callData: poolInterface.encodeFunctionData("liquidity", [])
    }
  ]);
  try {
    const [, returnData] = await multicallContract.callStatic.aggregate(calls);
    const poolData = /* @__PURE__ */ new Map();
    Array.from(poolGroups.keys()).forEach((poolAddress, index) => {
      try {
        const baseIndex = index * 2;
        const slot0 = poolInterface.decodeFunctionResult("slot0", returnData[baseIndex]);
        const liquidity = poolInterface.decodeFunctionResult("liquidity", returnData[baseIndex + 1])[0];
        poolData.set(poolAddress, {
          sqrtPriceX96: slot0.sqrtPriceX96.toString(),
          tick: slot0.tick,
          liquidity: liquidity.toString()
        });
      } catch (error) {
        console.warn(`\u26A0\uFE0F [V3 ENHANCE] Failed to decode pool data for ${poolAddress}:`, error);
      }
    });
    return positions.map((pos) => {
      try {
        const freshPoolData = poolData.get(pos.poolId);
        if (!freshPoolData || !pos.tickLower || !pos.tickUpper || !pos.liquidity) {
          return pos;
        }
        const token0 = pos.currency0Amount.currency;
        const token1 = pos.currency1Amount.currency;
        const feeTier = pos.feeTier || FeeAmount.MEDIUM;
        const freshPool = new V3Pool(
          token0,
          token1,
          feeTier,
          freshPoolData.sqrtPriceX96,
          freshPoolData.liquidity,
          freshPoolData.tick
        );
        const freshPosition = new V3Position({
          pool: freshPool,
          liquidity: pos.liquidity,
          tickLower: parseInt(pos.tickLower),
          tickUpper: parseInt(pos.tickUpper)
        });
        const enhancedCurrency0Amount = freshPosition.amount0;
        const enhancedCurrency1Amount = freshPosition.amount1;
        console.log(`\u2705 [V3 ENHANCE] Position ${pos.tokenId}:`, {
          oldAmount0: pos.currency0Amount.toSignificant(6),
          newAmount0: enhancedCurrency0Amount.toSignificant(6),
          oldAmount1: pos.currency1Amount.toSignificant(6),
          newAmount1: enhancedCurrency1Amount.toSignificant(6),
          tick: freshPoolData.tick
        });
        const updatedStatus = deriveV3PositionStatus({
          liquidity: pos.liquidity,
          tickLower: pos.tickLower !== void 0 ? Number.parseInt(pos.tickLower, 10) : void 0,
          tickUpper: pos.tickUpper !== void 0 ? Number.parseInt(pos.tickUpper, 10) : void 0,
          poolTick: freshPool.tickCurrent,
          fallback: pos.status
        });
        return {
          ...pos,
          currency0Amount: enhancedCurrency0Amount,
          currency1Amount: enhancedCurrency1Amount,
          pool: freshPool,
          position: freshPosition,
          status: updatedStatus
        };
      } catch (error) {
        console.warn(`\u26A0\uFE0F [V3 ENHANCE] Failed to enhance position ${pos.tokenId}:`, error);
        return pos;
      }
    });
  } catch (error) {
    console.error("\u274C [V3 ENHANCE] Multicall failed:", error);
    return positions;
  }
}
export function useEnhancePositionsWithMulticall(positions, userAddress, chainId) {
  const provider = useEthersProvider({ chainId });
  return useQuery({
    queryKey: ["enhance-positions-multicall", positions?.length, userAddress, chainId],
    queryFn: async () => {
      if (!positions || !provider || !userAddress) return positions || [];
      const v2Positions = positions.filter((pos) => pos.version === ProtocolVersion.V2);
      const v3Positions = positions.filter((pos) => pos.version === ProtocolVersion.V3);
      console.log(`\u{1F504} [ENHANCE] Processing ${v2Positions.length} V2 and ${v3Positions.length} V3 positions...`);
      const [enhancedV2, enhancedV3] = await Promise.all([
        enhanceV2Positions(v2Positions, provider, userAddress, chainId),
        enhanceV3Positions(v3Positions, provider, chainId)
      ]);
      const enhanced = [...enhancedV2, ...enhancedV3];
      console.log(`\u2705 [ENHANCE] Enhanced ${enhanced.length} positions`);
      return enhanced;
    },
    enabled: !!positions && !!provider && !!userAddress,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4
    // 1 minute (matches position page refresh)
  });
}
